#!/usr/bin/env bash
set -Eeuo pipefail
umask 077
[[ $EUID == 0 && $(uname -s) == Linux && $(uname -m) == x86_64 ]] || { echo 'Run as root on Linux amd64'; exit 1; }
command -v python3 >/dev/null || { echo 'Python 3 is required to open the installation panel'; exit 1; }
work=$(mktemp -d /var/tmp/ultrafull-commercial.XXXXXXXX)
chmod 700 "$work"
trap 'rm -rf -- "$work"' EXIT
cat > "$work/bootstrap.py" <<'ULTRAFULL_PYTHON'
import base64,json,pathlib,sys,os
root=pathlib.Path(__file__).resolve().parent
bundle=root/'bootstrap.zip';bundle.write_bytes(base64.b64decode(''))
sys.path.insert(0,str(bundle))
(root/'edition.json').write_text(json.dumps({'product': 'ULTRAFULL', 'version': '0.2.3', 'authority': 'https://ultraradar.ultranec.pro:9448', 'verify_key': 'f73170b1de1eb7c0b04e6abae68a5587f1f6d6fdbd76747c56ae5c9fb8072ce9'}))
from ufcommercial import common
common.APP=root
from ufcommercial.installer_ui import run
try:
 run({'product': 'ULTRAFULL', 'version': '0.2.3', 'authority': 'https://ultraradar.ultranec.pro:9448', 'verify_key': 'f73170b1de1eb7c0b04e6abae68a5587f1f6d6fdbd76747c56ae5c9fb8072ce9'},folder=root)
except KeyboardInterrupt:
 pass
except Exception:
 print('ULTRAFULL could not open the installer. Use an interactive SSH terminal with TERM=xterm-256color.')
 raise SystemExit(1) from None

ULTRAFULL_PYTHON
python3 "$work/bootstrap.py"
